#!/bin/sh
# Proves a task map's scripts on a throwaway copy; the real folder does not change.
# Usage: sh <plugin>/template/selftest.sh <plan-dir>
# Exits 0 when every check passes. The --json check needs jq.
# The selftest output is in the package language.

language='en'
# >>> strings (area selftest.): generated by tools/script-strings.sh from core/i18n/*.json; do not edit by hand
case "$language" in
  [Xx]-[Tt][Ee][Ss][Tt]) msg_language="x-test" ;;
  [Pp][Tt]-[Bb][Rr]) msg_language="pt-BR" ;;
  [Pp][Tt]|[Pp][Tt]-*) msg_language="pt-BR" ;;
  *) msg_language="en" ;;
esac
# shellcheck disable=SC2016,SC2089 # backticks and quotes in the strings are text, not expansion
case "$msg_language" in
  x-test) MSG_TABLE='selftest.usage	x-test:selftest.usage
selftest.fail	x-test:selftest.fail
selftest.statusValid	x-test:selftest.statusValid
selftest.mapNoCycle	x-test:selftest.mapNoCycle
selftest.jsonNoJq	x-test:selftest.jsonNoJq
selftest.jsonValid	x-test:selftest.jsonValid
selftest.jsonConsistent	x-test:selftest.jsonConsistent {0}
selftest.jsonInconsistent	x-test:selftest.jsonInconsistent {0} {1} {2} {3} {4} {5}
selftest.profileSame	x-test:selftest.profileSame {0}
selftest.profileDiffers	x-test:selftest.profileDiffers {0} {1}
selftest.leanClean	x-test:selftest.leanClean
selftest.leanLeftover	x-test:selftest.leanLeftover {0}
selftest.claimBlockedAccepted	x-test:selftest.claimBlockedAccepted {0}
selftest.claimBlockedRefused	x-test:selftest.claimBlockedRefused {0}
selftest.claimBlockedUnnamed	x-test:selftest.claimBlockedUnnamed {0} {1}
selftest.noBlocked	x-test:selftest.noBlocked
selftest.noFree	x-test:selftest.noFree
selftest.claimOk	x-test:selftest.claimOk {0}
selftest.closeAccepted	x-test:selftest.closeAccepted {0}
selftest.closeRefused	x-test:selftest.closeRefused {0}
selftest.releaseOk	x-test:selftest.releaseOk {0}
selftest.giveupUntouched	x-test:selftest.giveupUntouched {0}
selftest.giveupChanged	x-test:selftest.giveupChanged {0}
selftest.allGood	x-test:selftest.allGood {0}
selftest.failures	x-test:selftest.failures {0}
' ;;
  pt-BR) MSG_TABLE='selftest.usage	Uso: sh selftest.sh <plan-dir> (a pasta precisa de status.sh)
selftest.fail	FALHA
selftest.statusValid	status.sh sem (?), estado inválido nem ID repetido
selftest.mapNoCycle	map.sh sem ciclo
selftest.jsonNoJq	status.sh --json: jq ausente, não há como provar
selftest.jsonValid	status.sh --json válido com contract 1
selftest.jsonConsistent	status.sh --json válido e coerente com o texto ({0} tasks)
selftest.jsonInconsistent	status.sh --json coerente com o texto — progresso «{0}» vs «{1}», tasks {2} vs {3}, paralelas «{4}» vs «{5}»
selftest.profileSame	perfil {0}: o --json repete o plan.json
selftest.profileDiffers	perfil: --json «{0}», plan.json «{1}»
selftest.leanClean	perfil lean: sem spec/, research/ nem prototypes/
selftest.leanLeftover	perfil lean com {0}
selftest.claimBlockedAccepted	claim {0} (bloqueada) devia recusar
selftest.claimBlockedRefused	claim {0} recusada: a task bloqueada espera outra
selftest.claimBlockedUnnamed	claim {0} recusou sem nomear o bloqueio: {1}
selftest.noBlocked	nenhuma task bloqueada para provar a recusa
selftest.noFree	nenhuma task livre para provar claim/close/release
selftest.claimOk	claim {0} grava Started: e o status.sh mostra a duração
selftest.closeAccepted	close {0} com critério por marcar devia recusar
selftest.closeRefused	close {0} recusa com itens por marcar
selftest.releaseOk	release {0} volta a ready sem Started:
selftest.giveupUntouched	giveup {0} sem --yes não muda nada
selftest.giveupChanged	giveup {0} sem --yes mudou arquivos
selftest.allGood	Selftest: tudo certo (cópia apagada; {0} intacta)
selftest.failures	Selftest: {0} falha(s)
' ;;
  *) MSG_TABLE='selftest.usage	Usage: sh selftest.sh <plan-dir> (the folder needs status.sh)
selftest.fail	FAIL
selftest.statusValid	status.sh without (?), an invalid state or a duplicated ID
selftest.mapNoCycle	map.sh without a cycle
selftest.jsonNoJq	status.sh --json: jq missing, no way to prove it
selftest.jsonValid	status.sh --json valid with contract 1
selftest.jsonConsistent	status.sh --json valid and consistent with the text ({0} tasks)
selftest.jsonInconsistent	status.sh --json consistent with the text — progress "{0}" vs "{1}", tasks {2} vs {3}, parallel "{4}" vs "{5}"
selftest.profileSame	profile {0}: --json repeats plan.json
selftest.profileDiffers	profile: --json "{0}", plan.json "{1}"
selftest.leanClean	lean profile: no spec/, research/ or prototypes/
selftest.leanLeftover	lean profile with {0}
selftest.claimBlockedAccepted	claim {0} (blocked) should refuse
selftest.claimBlockedRefused	claim {0} refused: the blocked task waits on another
selftest.claimBlockedUnnamed	claim {0} refused without naming the blocker: {1}
selftest.noBlocked	no blocked task to prove the refusal
selftest.noFree	no free task to prove claim/close/release
selftest.claimOk	claim {0} writes Started: and status.sh shows the duration
selftest.closeAccepted	close {0} with an unchecked criterion should refuse
selftest.closeRefused	close {0} refuses with unchecked items
selftest.releaseOk	release {0} goes back to ready without Started:
selftest.giveupUntouched	giveup {0} without --yes changes nothing
selftest.giveupChanged	giveup {0} without --yes changed files
selftest.allGood	Selftest: all good (copy deleted; {0} untouched)
selftest.failures	Selftest: {0} failure(s)
' ;;
esac
# shellcheck disable=SC2090 # a table read by awk from the environment, never split by the shell
export MSG_TABLE
MSG_AWK='
function msg_load(   m, ls, j, p) {
  msg_ok = 1
  m = split(ENVIRON["MSG_TABLE"], ls, "\n")
  for (j = 1; j <= m; j++) { p = index(ls[j], "\t"); if (p > 0) MSG[substr(ls[j], 1, p - 1)] = substr(ls[j], p + 1) }
}
function msg(k, a0, a1, a2, a3, a4, a5,   s, r, i, c) {
  if (!msg_ok) msg_load()
  s = (k in MSG) ? MSG[k] : k
  r = ""
  while ((i = index(s, "{")) > 0) {
    c = substr(s, i + 1, 2)
    if (c ~ /^[0-5][}]$/) {
      c = substr(c, 1, 1)
      r = r substr(s, 1, i - 1) (c == "0" ? a0 : (c == "1" ? a1 : (c == "2" ? a2 : (c == "3" ? a3 : (c == "4" ? a4 : a5)))))
      s = substr(s, i + 3)
    } else { r = r substr(s, 1, i); s = substr(s, i + 1) }
  }
  return r s
}
'
msg() { awk "$MSG_AWK"' BEGIN { print msg(ARGV[1], ARGV[2], ARGV[3], ARGV[4], ARGV[5], ARGV[6], ARGV[7]); exit }' "$@"; }
# <<< strings

dir=$1
if [ -z "$dir" ] || [ ! -f "$dir/status.sh" ]; then
  msg selftest.usage >&2
  exit 1
fi
name=$(basename "$dir")
tmp=$(mktemp -d "${TMPDIR:-/tmp}/selftest.XXXXXX") || exit 1
# an interrupt in the middle must not leave the copy of the plan behind
trap 'cd / && rm -rf "$tmp"' EXIT
trap 'exit 1' HUP INT TERM
cp -R "$dir" "$tmp/" || exit 1
cd "$tmp/$name" || exit 1
# task.sh locks belong to the real folder: copied, they would make the copy's claim wait for a session that is not here
rm -rf .lock-*
# The text output follows the plan.json language; the checks below read the text of the plan
# scripts (headers, "for", "waits", "unchecked"), so the copy switches to the x-test language,
# in which each string is its i18n key: the checks depend neither on the translation nor on the
# package language. Each language's strings are proven by the template suite.
if [ -f plan.json ]; then
  awk '
    !done && /"language"[ \t]*:[ \t]*"[^"]*"/ { sub(/"language"[ \t]*:[ \t]*"[^"]*"/, "\"language\": \"x-test\""); done = 1 }
    { l[NR] = $0 }
    END {
      for (i = 1; i <= NR; i++) {
        if (!done && sub(/\{[ \t]*\}/, "{\"language\": \"x-test\"}", l[i])) done = 1
        if (!done && sub(/\{/, "{\"language\": \"x-test\", ", l[i])) done = 1
        print l[i]
      }
    }
  ' plan.json > plan.json.x && mv plan.json.x plan.json
else
  printf '%s\n' '{"language": "x-test"}' > plan.json
fi
failures=0
ok() { printf '  %-5s %s\n' ok "$1"; }
ko() { printf '  %-5s %s\n' "$(msg selftest.fail)" "$1"; failures=$((failures + 1)); }

out=$(sh status.sh)
if echo "$out" | grep -q -e '(?)' -e 'x-test:status.invalidStatus' -e 'x-test:status.duplicateId'; then ko "$(msg selftest.statusValid)"; else ok "$(msg selftest.statusValid)"; fi
if sh map.sh >/dev/null && ! grep -q 'x-test:map.cycle' MAP.md; then ok "$(msg selftest.mapNoCycle)"; else ko "$(msg selftest.mapNoCycle)"; fi

# --json valid and consistent with the text: progress, one entry per task, parallel sessions.
if ! command -v jq >/dev/null; then ko "$(msg selftest.jsonNoJq)"
elif ! json=$(sh status.sh --json) || ! printf '%s\n' "$json" | jq -e '.contract == 1' >/dev/null 2>&1; then ko "$(msg selftest.jsonValid)"
else
  pj=$(printf '%s\n' "$json" | jq -r '.progress | "\(.done) \(.total) \(.pct) \(.in_progress) \(.draft)"')
  pt=$(printf '%s\n' "$out" | sed -n 's/^x-test:status.progress //p')
  nj=$(printf '%s\n' "$json" | jq -r '.tasks | length')
  # shellcheck disable=SC2012 # only counts lines; task names have no line breaks
  nt=$(ls -1 phase-*/F[0-9]*.md | wc -l | tr -d ' ')
  parj=$(printf '%s\n' "$json" | jq -r '.parallel | join(" ")')
  part=$(printf '%s\n' "$out" | sed -n "s/^  x-test:status.session [0-9]* //p" | tr '\n' ' ' | sed 's/ $//')
  if [ "$pj" = "$pt" ] && [ "$nj" = "$nt" ] && [ "$parj" = "$part" ]; then ok "$(msg selftest.jsonConsistent "$nj")"
  else ko "$(msg selftest.jsonInconsistent "$pj" "$pt" "$nj" "$nt" "$parj" "$part")"; fi
  # profile: the --json one is the plan.json one (full when missing); lean has none of the folders the profile drops
  profile=$(printf '%s\n' "$json" | jq -r .profile)
  expected=full
  [ -f plan.json ] && expected=$(jq -r '.profile // "full"' plan.json 2>/dev/null)
  if [ "$profile" = "$expected" ]; then ok "$(msg selftest.profileSame "$profile")"; else ko "$(msg selftest.profileDiffers "$profile" "$expected")"; fi
  if [ "$profile" = lean ]; then
    leftover=$(for d in spec research prototypes; do [ -e "$d" ] && printf '%s/ ' "$d"; done)
    if [ -z "$leftover" ]; then ok "$(msg selftest.leanClean)"; else ko "$(msg selftest.leanLeftover "${leftover% }")"; fi
  fi
fi

blocked=$(echo "$out" | sed -n '/^x-test:status.waiting /,/^$/p' | awk 'NR == 2 { print $1 }')
if [ -n "$blocked" ]; then
  if reply=$(sh task.sh claim "$blocked" 2>&1); then ko "$(msg selftest.claimBlockedAccepted "$blocked")"; else
    case "$reply" in
      *x-test:task.stillWaiting*) ok "$(msg selftest.claimBlockedRefused "$blocked")" ;;
      *) ko "$(msg selftest.claimBlockedUnnamed "$blocked" "$reply")" ;;
    esac
  fi
else
  printf '  —     %s\n' "$(msg selftest.noBlocked)"
fi

free=$(sh status.sh --options | head -1 | cut -f1)
if [ -z "$free" ]; then
  ko "$(msg selftest.noFree)"
else
  if sh task.sh claim "$free" >/dev/null 2>&1 && sed -n '1,/^# /p' phase-*/"$free"[!0-9.]*.md | grep -q '^Started:' && sh status.sh | grep -q "^  $free .*x-test:status.ago "; then
    ok "$(msg selftest.claimOk "$free")"
  else ko "claim $free"; fi
  if reply=$(sh task.sh close "$free" 2>&1); then ko "$(msg selftest.closeAccepted "$free")"; else
    case "$reply" in *x-test:task.doneWhenUnchecked*) ok "$(msg selftest.closeRefused "$free")" ;; *) ko "close $free: $reply" ;; esac
  fi
  if sh task.sh release "$free" >/dev/null 2>&1 && [ "$(sed -n 1p phase-*/"$free"[!0-9.]*.md)" = "Status: ready" ] && ! sed -n '1,/^# /p' phase-*/"$free"[!0-9.]*.md | grep -q '^Started:'; then
    ok "$(msg selftest.releaseOk "$free")"
  else ko "release $free"; fi
  # the giveup preview (without --yes) changes no file, accepted or refused
  before=$(cat phase-*/*.md)
  sh task.sh giveup "$free" >/dev/null 2>&1
  if [ "$(cat phase-*/*.md)" = "$before" ]; then ok "$(msg selftest.giveupUntouched "$free")"; else ko "$(msg selftest.giveupChanged "$free")"; fi
fi

cd / && rm -rf "$tmp"
if [ "$failures" -eq 0 ]; then msg selftest.allGood "$dir"; else msg selftest.failures "$failures"; exit 1; fi
